+const parse = <T>(schema: z.ZodType<T>, value: unknown): T => {
+  const result = schema.safeParse(value);
+  if (!result.success) {
+    throw new AppError(
+      400,
+      'bad_request',
+      'Request validation failed.',
+      result.error.issues,
+    );
+  }
+  return result.data;
+};
+
+const writeEvent = (reply: FastifyReply, event: SseEvent) => {
+  reply.raw.write(`event: message\ndata: ${JSON.stringify(event)}\n\n`);
+};
+
+const stream = async (
+  reply: FastifyReply,
+  events: AsyncGenerator<SseEvent>,
+) => {
+  let first: IteratorResult<SseEvent>;
+  try {
+    first = await events.next();
+  } catch (error) {
+    throw error;
+  }
+  reply.hijack();
+  reply.raw.writeHead(200, {
+    'Content-Type': 'text/event-stream',
+    'Cache-Control': 'no-cache',
+    Connection: 'keep-alive',
+  });
+  try {
+    if (!first.done) writeEvent(reply, first.value);
+    for await (const event of events) writeEvent(reply, event);
+  } catch (error) {
+    const appError =
+      error instanceof AppError
+        ? error
+        : new AppError(500, 'internal', 'Streaming failed.');
+    writeEvent(reply, {
+      type: 'done',
+      unsupported: true,
+    });
+    reply.raw.write(
+      `event: error\ndata: ${JSON.stringify({
+        type: 'error',
+        code: appError.code,
+        message: appError.message,
+      })}\n\n`,
+    );
+  } finally {
+    reply.raw.end();
+  }
